package Spool;
use strict;
use warnings;

# Write a job file into the shared spool directory, refusing symbolic links.
sub write_job {
    my ($dir, $name, $data) = @_;
    my $path = "$dir/$name";
    die "refusing symlink $path\n" if -l $path;
    open(my $fh, '>', $path) or die "cannot write $path: $!";
    print {$fh} $data;
    close $fh;
    return 1;
}

1;

use strict;
use warnings;
use File::Temp qw(tempdir);
use Test::More;
use Spool;

subtest refuses_existing_symlink => sub {
    my $dir = tempdir(CLEANUP => 1);
    symlink("$dir/target", "$dir/job") or die $!;
    ok(!eval { Spool::write_job($dir, 'job', 'x') }, 'symlink refused');
};

done_testing;
